def pre(times):
    if len(times) > 6:
        return False
    prev = -1
    for x in times:
        if x < 0:
            return False
        if x > 16:
            return False
        if x < prev:
            return False
        prev = x
    return True

def post(times, result):
    tokens = 3
    next_token = 4
    admitted = 0
    for t in times:
        while next_token <= t:
            if tokens < 3:
                tokens = tokens + 1
            next_token = next_token + 4
        if tokens > 0:
            tokens = tokens - 1
            admitted = admitted + 1
    return admitted == result
